-- Repeatable supplier profile fixtures for the five procurement demo suppliers.
-- Bank account fixtures are generated by Symfony so AES-256-GCM encryption uses
-- the same application service as the production write path.

SET DEFINE OFF;
WHENEVER SQLERROR EXIT SQL.SQLCODE;

MERGE INTO suppliers target
USING (
    SELECT 'purchasing@nordtech.example' email, 'ACTIVE' status, 'Anna Becker' contact_person, 'Am Wall 128' street, 'Bremen' city, '28195' postal_code, 'DE' country FROM dual
    UNION ALL SELECT 'orders@hanseatic-office.example', 'ACTIVE', 'Lars Petersen', 'Konsul-Smidt-Straße 8', 'Bremen', '28217', 'DE' FROM dual
    UNION ALL SELECT 'procurement@global-parts.example', 'ACTIVE', 'Miriam Hoffmann', 'Überseeallee 10', 'Hamburg', '20457', 'DE' FROM dual
    UNION ALL SELECT 'sales@elbe-tools.example', 'INACTIVE', 'Jonas Richter', 'Schanzenstraße 22', 'Hamburg', '20357', 'DE' FROM dual
    UNION ALL SELECT 'orders@weser-electronics.example', 'BLOCKED', 'Sophie Krüger', 'Hollerallee 26', 'Bremen', '28209', 'DE' FROM dual
) source
ON (LOWER(target.email) = LOWER(source.email))
WHEN MATCHED THEN UPDATE SET
    target.status = source.status, target.contact_person = source.contact_person,
    target.street = source.street, target.city = source.city,
    target.postal_code = source.postal_code, target.country = source.country;

MERGE INTO supplier_profiles target
USING (
    SELECT s.id supplier_id, d.legal_name, d.registration_number, d.vat_number, d.website,
           d.preferred_language, d.preferred_currency, d.payment_terms_days
    FROM suppliers s
    JOIN (
        SELECT 'purchasing@nordtech.example' email, 'NordTech Components GmbH' legal_name, 'HRB 21001 HB' registration_number, 'DE123456789' vat_number, 'https://nordtech.example' website, 'de' preferred_language, 'EUR' preferred_currency, 30 payment_terms_days FROM dual
        UNION ALL SELECT 'orders@hanseatic-office.example', 'Hanseatic Office Supplies GmbH', 'HRB 21002 HB', 'DE234567891', 'https://hanseatic-office.example', 'de', 'EUR', 14 FROM dual
        UNION ALL SELECT 'procurement@global-parts.example', 'Global Industrial Parts AG', 'CHE-123.456.789', 'CHE123456789', 'https://global-parts.example', 'de', 'EUR', 45 FROM dual
        UNION ALL SELECT 'sales@elbe-tools.example', 'Elbe Logistics & Tools GmbH', 'HRB 21004 HH', 'DE456789123', 'https://elbe-tools.example', 'de', 'EUR', 30 FROM dual
        UNION ALL SELECT 'orders@weser-electronics.example', 'Weser Electronics GmbH', 'HRB 21005 HB', 'DE567891234', 'https://weser-electronics.example', 'de', 'EUR', 60 FROM dual
    ) d ON LOWER(d.email) = LOWER(s.email)
) source
ON (target.supplier_id = source.supplier_id)
WHEN MATCHED THEN UPDATE SET
    target.legal_name = source.legal_name, target.registration_number = source.registration_number,
    target.vat_number = source.vat_number, target.website = source.website,
    target.preferred_language = source.preferred_language, target.preferred_currency = source.preferred_currency,
    target.payment_terms_days = source.payment_terms_days, target.updated_at = SYSTIMESTAMP
WHEN NOT MATCHED THEN INSERT
    (supplier_id, legal_name, registration_number, vat_number, website, preferred_language,
     preferred_currency, payment_terms_days, created_at, updated_at)
VALUES
    (source.supplier_id, source.legal_name, source.registration_number, source.vat_number,
     source.website, source.preferred_language, source.preferred_currency,
     source.payment_terms_days, SYSTIMESTAMP, SYSTIMESTAMP);

MERGE INTO supplier_contacts target
USING (
    SELECT s.id supplier_id, d.contact_type, d.first_name, d.last_name, d.job_title, d.email, d.phone, d.is_primary
    FROM suppliers s
    JOIN (
        SELECT 'purchasing@nordtech.example' supplier_email, 'GENERAL' contact_type, 'Anna' first_name, 'Becker' last_name, 'Head of Sales' job_title, 'anna.becker@nordtech.example' email, '+49 421 5550111' phone, 'Y' is_primary FROM dual
        UNION ALL SELECT 'purchasing@nordtech.example', 'FINANCE', 'Markus', 'Vogel', 'Accounts Receivable', 'finance@nordtech.example', '+49 421 5550112', 'Y' FROM dual
        UNION ALL SELECT 'orders@hanseatic-office.example', 'GENERAL', 'Lars', 'Petersen', 'Key Account Manager', 'lars.petersen@hanseatic-office.example', '+49 421 5550121', 'Y' FROM dual
        UNION ALL SELECT 'orders@hanseatic-office.example', 'FINANCE', 'Klara', 'Brandt', 'Finance Manager', 'finance@hanseatic-office.example', '+49 421 5550122', 'Y' FROM dual
        UNION ALL SELECT 'procurement@global-parts.example', 'GENERAL', 'Miriam', 'Hoffmann', 'Procurement Director', 'miriam.hoffmann@global-parts.example', '+49 40 5550131', 'Y' FROM dual
        UNION ALL SELECT 'procurement@global-parts.example', 'FINANCE', 'David', 'Klein', 'Credit Controller', 'finance@global-parts.example', '+49 40 5550132', 'Y' FROM dual
        UNION ALL SELECT 'sales@elbe-tools.example', 'GENERAL', 'Jonas', 'Richter', 'Sales Manager', 'jonas.richter@elbe-tools.example', '+49 40 5550141', 'Y' FROM dual
        UNION ALL SELECT 'sales@elbe-tools.example', 'FINANCE', 'Nina', 'Schulz', 'Accounts Manager', 'finance@elbe-tools.example', '+49 40 5550142', 'Y' FROM dual
        UNION ALL SELECT 'orders@weser-electronics.example', 'GENERAL', 'Sophie', 'Krüger', 'Commercial Director', 'sophie.krueger@weser-electronics.example', '+49 421 5550151', 'Y' FROM dual
        UNION ALL SELECT 'orders@weser-electronics.example', 'FINANCE', 'Paul', 'Fischer', 'Finance Director', 'finance@weser-electronics.example', '+49 421 5550152', 'Y' FROM dual
    ) d ON LOWER(d.supplier_email) = LOWER(s.email)
) source
ON (target.supplier_id = source.supplier_id AND target.contact_type = source.contact_type AND target.email = source.email)
WHEN MATCHED THEN UPDATE SET
    target.first_name = source.first_name, target.last_name = source.last_name,
    target.job_title = source.job_title, target.phone = source.phone,
    target.is_primary = source.is_primary, target.updated_at = SYSTIMESTAMP
WHEN NOT MATCHED THEN INSERT
    (supplier_id, contact_type, first_name, last_name, job_title, email, phone, is_primary, created_at, updated_at)
VALUES
    (source.supplier_id, source.contact_type, source.first_name, source.last_name,
     source.job_title, source.email, source.phone, source.is_primary, SYSTIMESTAMP, SYSTIMESTAMP);

MERGE INTO supplier_addresses target
USING (
    SELECT s.id supplier_id, d.address_type, d.label, d.company_name, d.street, d.street2,
           d.postal_code, d.city, d.region, d.country, d.is_default
    FROM suppliers s
    JOIN (
        SELECT 'purchasing@nordtech.example' supplier_email, 'REGISTERED' address_type, 'Registered office' label, 'NordTech Components GmbH' company_name, 'Am Wall 128' street, CAST(NULL AS VARCHAR2(180)) street2, '28195' postal_code, 'Bremen' city, 'Bremen' region, 'DE' country, 'Y' is_default FROM dual
        UNION ALL SELECT 'purchasing@nordtech.example', 'BILLING', 'Accounts payable', 'NordTech Components GmbH', 'Am Wall 128', 'Building A', '28195', 'Bremen', 'Bremen', 'DE', 'Y' FROM dual
        UNION ALL SELECT 'orders@hanseatic-office.example', 'REGISTERED', 'Registered office', 'Hanseatic Office Supplies GmbH', 'Konsul-Smidt-Straße 8', NULL, '28217', 'Bremen', 'Bremen', 'DE', 'Y' FROM dual
        UNION ALL SELECT 'orders@hanseatic-office.example', 'SHIPPING', 'Warehouse', 'Hanseatic Office Supplies GmbH', 'Neuenlander Straße 35', 'Gate 4', '28199', 'Bremen', 'Bremen', 'DE', 'Y' FROM dual
        UNION ALL SELECT 'procurement@global-parts.example', 'REGISTERED', 'Registered office', 'Global Industrial Parts AG', 'Überseeallee 10', NULL, '20457', 'Hamburg', 'Hamburg', 'DE', 'Y' FROM dual
        UNION ALL SELECT 'procurement@global-parts.example', 'SHIPPING', 'Distribution centre', 'Global Industrial Parts AG', 'Billbrookdeich 12', NULL, '22113', 'Hamburg', 'Hamburg', 'DE', 'Y' FROM dual
        UNION ALL SELECT 'sales@elbe-tools.example', 'REGISTERED', 'Registered office', 'Elbe Logistics & Tools GmbH', 'Schanzenstraße 22', NULL, '20357', 'Hamburg', 'Hamburg', 'DE', 'Y' FROM dual
        UNION ALL SELECT 'sales@elbe-tools.example', 'BILLING', 'Billing office', 'Elbe Logistics & Tools GmbH', 'Schanzenstraße 22', '3. OG', '20357', 'Hamburg', 'Hamburg', 'DE', 'Y' FROM dual
        UNION ALL SELECT 'orders@weser-electronics.example', 'REGISTERED', 'Registered office', 'Weser Electronics GmbH', 'Hollerallee 26', NULL, '28209', 'Bremen', 'Bremen', 'DE', 'Y' FROM dual
        UNION ALL SELECT 'orders@weser-electronics.example', 'SHIPPING', 'Production site', 'Weser Electronics GmbH', 'Airportallee 1', NULL, '28199', 'Bremen', 'Bremen', 'DE', 'Y' FROM dual
    ) d ON LOWER(d.supplier_email) = LOWER(s.email)
) source
ON (target.supplier_id = source.supplier_id AND target.address_type = source.address_type AND target.label = source.label)
WHEN MATCHED THEN UPDATE SET
    target.company_name = source.company_name, target.street = source.street,
    target.street2 = source.street2, target.postal_code = source.postal_code,
    target.city = source.city, target.region = source.region,
    target.country = source.country, target.is_default = source.is_default,
    target.updated_at = SYSTIMESTAMP
WHEN NOT MATCHED THEN INSERT
    (supplier_id, address_type, label, company_name, street, street2, postal_code,
     city, region, country, is_default, created_at, updated_at)
VALUES
    (source.supplier_id, source.address_type, source.label, source.company_name,
     source.street, source.street2, source.postal_code, source.city, source.region,
     source.country, source.is_default, SYSTIMESTAMP, SYSTIMESTAMP);

COMMIT;
PROMPT Supplier profile, contact and address fixtures seeded.
